var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/projects/%7Bproject_id%7D/work_order_contracts/%7Bcontract_id%7D/compliance_documents?page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
